mapper.select:
select p.id from pms_sku s join pms_product p on p.id = s.product_id
where s.id = #{skuId} and p.merchant_id = #{merchantId}
  and (p.del_flag is null or p.del_flag = 0)

select v.id from verification_review_evidence e join verification_review v on v.id = e.review_id
where e.id = #{evidenceId} and e.owner_member_id = #{ownerMemberId}
  and v.verifier_member_id = #{ownerMemberId}

mapper.update:
update merchant_redemption_anchor
set anchor_lat = #{anchorLat}, anchor_lng = #{anchorLng}, radius_m = #{radiusM},
    wifi_bssid_hashes = #{wifiBssidHashes}, owner_member_id = #{ownerMemberId},
    version = version + 1, updated_by = #{updatedBy}, updated_at = #{now}
where merchant_id = #{merchantId} and version = #{expectedVersion}

update pms_sku s
join pms_product p on p.id = s.product_id
set s.sku_name = #{skuName}, s.price = #{price}, s.original_price = #{originalPrice}, s.pic = #{pic},
    s.stock = #{stock}, s.update_by = #{actor}, s.update_time = #{now}
where s.id = #{skuId} and s.product_id = #{productId} and p.merchant_id = #{merchantId}
  and p.publish_status <> 1 and (p.del_flag is null or p.del_flag = 0)

update pms_sku_booking_rule
set bookable = #{bookable}, slot_minutes = #{slotMinutes}, capacity_per_slot = #{capacityPerSlot},
    version = version + 1, updated_by = #{updatedBy}, updated_at = #{now}
where sku_id = #{skuId} and merchant_id = #{merchantId} and version = #{expectedVersion}

mapper.select:
select id as slotId, sku_id as skuId, slot_start as slotStart, slot_end as slotEnd, capacity_total as capacityTotal, capacity_reserved as capacityReserved, status, source_batch as sourceBatch from pms_sku_capacity_slot where merchant_id = #{merchantId} and sku_id = #{skuId} and slot_start >= #{from} and slot_start < #{to}
and (slot_start > #{afterStart} or (slot_start = #{afterStart} and id > #{afterSlotId}))
order by slot_start asc, id asc limit 101
